window.docContents[194].resolve({"/7___-Introduction-to-categories/7___2___-Functors/Functor/#Chapter7___Definition7___2___1":{"contents":"Definition 7.2.1. A functor F : \\mathcal{C} \\to \\mathcal{D} between categories \\mathcal{C} and \\mathcal{D} is\n\n(i) a map F : Ob(\\mathcal{C}) \\to Ob(\\mathcal{D});\n(ii) for each X, Y \\in \\mathcal{C}, a map F = F_{X,Y} : \\operatorname{Hom}(X, Y) \\to \\operatorname{Hom}(F(X), F(Y)) which preserves compositions and identity morphisms.\n\n\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories\t7.2. Functors\tFunctor","header":"Functor","id":"/7___-Introduction-to-categories/7___2___-Functors/Functor/#Chapter7___Definition7___2___1"},"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Lie-algebra/#Chapter2___Definition2___9___1":{"contents":"Definition 2.9.1. (\\mathfrak{g}, [\\ ,\\ ]) is a Lie algebra if [\\ ,\\ ] satisfies the Jacobi identity\n\n(2.9.1) \\qquad [[a, b], c] + [[b, c], a] + [[c, a], b] = 0.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.9. Lie algebras\tLie algebra","header":"Lie algebra","id":"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Lie-algebra/#Chapter2___Definition2___9___1"},"/3___-General-results-of-representation-theory/3___1___-Subrepresentations-in-semisimple-representations/Generalization-of-Proposition-3___1___4-to-non-algebraically-closed-fields/#Chapter3___Remark3___1___5":{"contents":"Remark 3.1.5. In Proposition 3.1.4, it is not important that k is algebraically closed, nor does it matter that V is finite dimensional. If these assumptions are dropped, the only change needed is that the entries of the matrix X_i are no longer in k but in D_i = \\operatorname{End}_A(V_i), which is, as we know, a division algebra. The proof of this generalized version of Proposition 3.1.4 is the same as before (check it!).\n\n\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory\t3.1. Subrepresentations in semisimple representations\tGeneralization of Proposition 3.1.4 to non-algebraically-closed fields","header":"Generalization of Proposition 3.1.4 to non-algebraically-closed fields","id":"/3___-General-results-of-representation-theory/3___1___-Subrepresentations-in-semisimple-representations/Generalization-of-Proposition-3___1___4-to-non-algebraically-closed-fields/#Chapter3___Remark3___1___5"},"/5___-Representations-of-finite-groups___-Further-results/5___18___-Schur-Weyl-duality-for-______mathfrak___gl____LPAR_V_RPAR____/Section-5___18___-Schur-Weyl-duality-for-gl_LPAR_V_RPAR_-___-Double-Centralizer-Theorem/#Chapter5___Introduction_5___18___heading-1":{"contents":"We start with a simple result which is called the Double Centralizer Theorem.\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.18. Schur-Weyl duality for $\\mathfrak{gl}(V)$\tSection 5.18: Schur-Weyl duality for gl(V) — Double Centralizer Theorem","header":"5.18. Schur-Weyl duality for  \\mathfrak{gl}(V)","id":"/5___-Representations-of-finite-groups___-Further-results/5___18___-Schur-Weyl-duality-for-______mathfrak___gl____LPAR_V_RPAR____/Section-5___18___-Schur-Weyl-duality-for-gl_LPAR_V_RPAR_-___-Double-Centralizer-Theorem/#Chapter5___Introduction_5___18___heading-1"}});
